      resource "aws_db_instance" "example" {
        auto_minor_version_upgrade = true
      }

    Out of band — aws_db_instance:

      aws rds modify-db-instance --db-instance-identifier <id> --auto-minor-version-upgrade --apply-immediately
  FIX

  tag checkov_id:            'CKV_AWS_226'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
